// Scoped (KPK market configurator only) snapshot of the Gearbox anvil Mainnet
// fork, replayed via `hydrate` so the test runs fully offline. The account
// data fixture is the pre-state of the credit account targeted by all sample
// multicalls, captured at the same block; it is passed to previews via
// `options.creditAccount` so they don't hit the credit account compressor.
//
// The account owes 40 WETH of principal with 122187064668312 wei of interest
// and fees accrued on top, and `totalDebt` is the whole of it — which is why the
// expectations below are 40 WETH plus that tail rather than round numbers.
// Regenerate both with `tsx scripts/generate-preview-adjust-ca-fixture.ts`.
const STATE_FIXTURE = resolve(
  import.meta.dirname,
  "../__fixtures__/Mainnet-25475508-adjust-credit-account.json",
);
const ACCOUNT_FIXTURE = resolve(
  import.meta.dirname,
  "../__fixtures__/Mainnet-25475508-adjust-credit-account-data.json",
);

// KPK WETH strategy credit facade all transactions call
const FACADE: Address = "0x9515AB9BB73A9642F1a93Ba7C2790e9d08227f9a";
const CREDIT_MANAGER: Address = "0x79C6C1ce5B12abCC3E407ce8C160eE1160250921";
const CREDIT_ACCOUNT: Address = "0xE22cEd1808c22455747F366Cf94d45B3201302d3";
const OWNER: Address = "0xC32FEB4DBd127a1993478Ad6E5250710f838b908";

const WETH: Address = "0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2";
const CBETH: Address = "0xBe9895146f7AF43049ca1c1AE358B0541Ea49704";

/**
 * An underlying-denominated amount, as the projection reports one: the market
 * is KPK WETH, so the token the figure names has to be WETH and not whichever
 * collateral the operation happened to move.
 */
const und = (value: unknown) => ({
  token: expect.objectContaining({ address: WETH }),
  value,
});

let sdk: OnchainSDK;
let creditAccount: CreditAccountData;

beforeAll(() => {
  sdk = new OnchainSDK("Mainnet", {
    transport: custom({
      request: async () => {
        throw new Error("offline: preview test must not hit RPC");
      },
    }),
  });
  sdk.hydrate(json_parse(readFileSync(STATE_FIXTURE, "utf-8")));
  creditAccount = json_parse(readFileSync(ACCOUNT_FIXTURE, "utf-8"));
});

// transactions are generated against the anvil Mainnet fork using frontend
// UI, but never sent; the account pre-state is ~44 cbETH with 40 WETH debt
async function preview(calldata: Hex) {
  const answer = await previewOperation(
    { sdk, to: FACADE, calldata, sender: OWNER, value: 0n },
    { creditAccount },
  );
  if (!answer.ok) {
    throw new Error(`preview refused: ${answer.error.code}`);
  }
  return answer.data;
}

it("previews raising leverage to 6", async () => {
  // withdrawCollateral(cbETH) + increaseDebt + bracketed WETH -> cbETH swap
  // + negative cbETH quota update
  const OP1: Hex =
    "";

  await expect(preview(OP1)).resolves.toMatchObject({
    operation: "AdjustCreditAccount",
    creditManager: CREDIT_MANAGER,
    creditAccount: CREDIT_ACCOUNT,
    name: expect.any(String),
    underlyingToken: expect.objectContaining({ address: WETH }),
    targetCollateral: expect.objectContaining({
      address: expect.stringMatching(/^0x/i),
    }),
    estLeverage: expect.any(Number),
    collateralAdded: [],
    collateralWithdrawn: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: 1_387_859_676_487_610_985n,
      },
    ],
    totalDebt: und(41_574_436_328_452_499_320n),
    totalDebtChange: und(1_574_314_141_387_831_008n),
    quotas: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: 46_360_419_898_114_650_000n,
      },
    ],
    quotasChange: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: -2_356_436_935_552_180_000n,
      },
    ],
    estAssets: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: 43_945_921_284_867_266_790n,
      },
    ],
    assetsChange: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: -34_681_141_736_785_841n,
      },
    ],
    estTotalValue: und(49_849_913_868_940_488_429n),
  });
});

