it("previews withdrawing 1 cbETH", async () => {
  // bracketed cbETH -> WETH swap + decreaseDebt + withdrawCollateral(cbETH)
  // + negative cbETH quota update
  const OP6: Hex =
    "";

  await expect(preview(OP6)).resolves.toMatchObject({
    operation: "AdjustCreditAccount",
    creditManager: CREDIT_MANAGER,
    creditAccount: CREDIT_ACCOUNT,
    collateralAdded: [],
    collateralWithdrawn: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: 999_999_999_999_999_999n,
      },
    ],
    totalDebt: und(35_369_517_375_080_970_375n),
    // A repayment is the one figure in the model that is negative, and the
    // USD side has to follow it down rather than clamp to zero.
    totalDebtChange: {
      token: expect.objectContaining({ address: WETH }),
      value: -4_630_604_811_983_697_937n,
      valueUsd: expect.toSatisfy((v: number) => v < 0),
    },
    quotas: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: 41_035_601_537_003_630_000n,
      },
    ],
    quotasChange: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: -7_681_255_296_663_200_000n,
      },
    ],
    estAssets: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: 38_898_424_970_816_037_377n,
      },
      {
        token: expect.objectContaining({ address: WETH }),
        value: 59_823_460_339_788_484n,
      },
    ],
    assetsChange: [
      {
        token: expect.objectContaining({ address: CBETH }),
        value: -5_082_177_455_788_015_254n,
      },
      {
        token: expect.objectContaining({ address: WETH }),
        value: 59_823_460_339_788_484n,
      },
    ],
    estTotalValue: und(44_184_126_188_300_681_109n),
  });
});

