it("reports an unpriceable-token error and keeps the best-effort preview", async () => {
  // Hand-crafted multicall adding collateral in a registered token the
  // oracle cannot price: the preview is still computed, the token
  // contributes nothing to totalValue and a 2xxx preview-limitation error
  // is reported.
  const UNKNOWN: Address = "0x1111111111111111111111111111111111111111";
  sdk.tokensMeta.upsert(UNKNOWN, {
    addr: UNKNOWN,
    decimals: 18,
    name: "Unknown",
    symbol: "UNK",
  });
  const amount = parseEther("1");
  const calldata = encodeFunctionData({
    abi: iCreditFacadeV310Abi,
    functionName: "multicall",
    args: [
      CREDIT_ACCOUNT,
      [
        {
          target: FACADE,
          callData: encodeFunctionData({
            abi: iCreditFacadeMulticallV310Abi,
            functionName: "addCollateral",
            args: [UNKNOWN, amount],
          }),
        },
      ],
    ],
  });

  const result = await preview(calldata);
  expect(result).toMatchObject({
    operation: "AdjustCreditAccount",
    creditManager: CREDIT_MANAGER,
    creditAccount: CREDIT_ACCOUNT,
    collateralAdded: [
      { token: expect.objectContaining({ address: UNKNOWN }), value: amount },
    ],
    totalDebt: und(40_000_122_187_064_668_312n),
    totalDebtChange: und(0n),
    // best-effort: the unknown token still appears in assets, but only the
    // priceable pre-state cbETH contributes to totalValue (see the
    // "adjusting leverage to 4" case above for the cbETH-only value)
    estAssets: expect.arrayContaining([
      expect.objectContaining({
        token: expect.objectContaining({ address: UNKNOWN }),
        value: amount,
      }),
    ]),
    estTotalValue: und(49_889_254_310_053_293_583n),
    error: { code: ERROR_UNPRICEABLE_TOKEN, message: expect.any(String) },
  });
});

it("reports the health factor at both pricings", async () => {
  // The safe factor values collateral at the lower of each token's main and
  // reserve feeds, so it can never read better than the main-price one — and
  // it is what the credit manager weighs a call that hands funds over against.
  const OP: Hex =
    "";

  const result = await preview(OP);
  if (result.operation !== "AdjustCreditAccount") {
    throw new Error("expected AdjustCreditAccount");
  }

  expect(result.estSafeHealthFactor).toEqual(expect.any(Number));
  expect(result.estSafeHealthFactor).toBeLessThanOrEqual(
    result.estHealthFactor,
  );
});
